insert into public.posts (board,title,content,author_name,is_notice,attachments,created_at,updated_at) select 'documents','2025년 직장내괴롭힘 및 직장내성희롱 예방 관련 자료 게시','<div class="box" style="margin-bottom:16px"><b>갑질(직장내 괴롭힘등) 캠페인</b> · 작성자 장소희 · 게시일 2025-12-24<br><a href="https://grilu.kr/archive/documents/000000nsm.html" style="color:var(--primary);text-decoration:underline;font-weight:700">▶ 본문·첨부파일 전문 보기</a></div><p style="line-height:1.8;color:#444">고용노동부에서 제작한 직장 내 괴롭힘 및 직장 내 성희롱 예방을 위한 교육 자료 및 홍보물을 붙임과 같이 게시하오니 많은 관심 부탁드립니다. (붙임1) 직장 내 괴롭힘 예방 교육 자료 (붙임2) 직장 내 괴롭힘 예방 포스터 (붙임3) 직장 내 성희롱 예방 포스터 (링크) 직장 내 성희롱 예방 교육 링크 http://youtube.com/watch?si=JoC98NZ6D0v3eerS&amp;v=XBV1jmygqVs&amp;feature=youtu.be ※ 출처 : 고용노동부 홈페이지</p><p class="note">첨부: (붙임1) 직장 내괴롭힘 예방·조치 교육자료_근로자용.pdf, (붙임2) 직장 내 괴롭힘 금지제도 홍보 포스터.png, (붙임3) 직장 내 성희롱 예방 대응 안내서 포스터.jpg</p>','장소희',false,'{"legacy_id": "gw-000000nsm", "page": "archive/documents/000000nsm.html", "files": ["(붙임1) 직장 내괴롭힘 예방·조치 교육자료_근로자용.pdf", "(붙임2) 직장 내 괴롭힘 금지제도 홍보 포스터.png", "(붙임3) 직장 내 성희롱 예방 대응 안내서 포스터.jpg"], "source": "gw.gri.re.kr 갑질(직장내 괴롭힘등) 캠페인"}'::jsonb,'2025-12-24'::date,'2025-12-24'::date where not exists (select 1 from public.posts where attachments->>'legacy_id' = 'gw-000000nsm');
