insert into public.posts (board,title,content,author_name,is_notice,attachments,created_at,updated_at) select 'documents','2021년 성희롱·성폭력 및 직장내 괴롭힘(2차 피해 포함) 예방 심화교육 자료게시','<div class="box" style="margin-bottom:16px"><b>갑질(직장내 괴롭힘등) 캠페인</b> · 작성자 장영자 · 게시일 2021-11-02<br><a href="https://grilu.kr/archive/documents/000000j48.html" style="color:var(--primary);text-decoration:underline;font-weight:700">▶ 본문·첨부파일 전문 보기</a></div><p style="line-height:1.8;color:#444">안전한 근무환경 조성을 위해 성희롱·성폭력 및 직장 내 괴롭힘(2차 피해 포함) 예방을 위한 직군별 심화교육을 7회차에 걸쳐 실시완료하였고, 해당 교육자료를 게시합니다. (직군별 교육내용 차별화 및 연구원 사례 반영)</p><p class="note">첨부: 2021년_성희롱·성폭력_및_괴롭힘_예방_심화교육강의안(연구위원등).pdf, 2021년_성희롱·성폭력_및_괴롭힘_예방_심화교육강의안(연구원,행정원등 대상).pdf</p>','장영자',false,'{"legacy_id": "gw-000000j48", "page": "archive/documents/000000j48.html", "files": ["2021년_성희롱·성폭력_및_괴롭힘_예방_심화교육강의안(연구위원등).pdf", "2021년_성희롱·성폭력_및_괴롭힘_예방_심화교육강의안(연구원,행정원등 대상).pdf"], "source": "gw.gri.re.kr 갑질(직장내 괴롭힘등) 캠페인"}'::jsonb,'2021-11-02'::date,'2021-11-02'::date where not exists (select 1 from public.posts where attachments->>'legacy_id' = 'gw-000000j48');
