insert into public.posts (board,title,content,author_name,is_notice,attachments,created_at,updated_at) select 'documents','성희롱·성폭력 신고 게시판 이용안내','<div class="box" style="margin-bottom:16px"><b>성희롱·성폭력 신고센터</b> · 작성자 장영자 · 게시일 2021-04-07<br><a href="https://grilu.kr/archive/documents/000000isw.html" style="color:var(--primary);text-decoration:underline;font-weight:700">▶ 본문·첨부파일 전문 보기</a></div><p style="line-height:1.8;color:#444">&lt;성희롱·성폭력 신고 게시판 이용안내&gt; &#x27;성희롱·성폭력 신고&#x27; 게시판은 비공개로 운영되며, 게시글은 작성자와 고충상담원만 볼 수 있습니다. (제목 및 내용, 작성자등이 게시판에 표출되지 않습니다)</p>','장영자',false,'{"legacy_id": "gw-000000isw", "page": "archive/documents/000000isw.html", "files": [], "source": "gw.gri.re.kr 성희롱·성폭력 신고센터"}'::jsonb,'2021-04-07'::date,'2021-04-07'::date where not exists (select 1 from public.posts where attachments->>'legacy_id' = 'gw-000000isw');
