update public.posts set board='statement', title='[2/18 GRI·경기도 기사] 경기도, 산하 공공기관 7곳 동·북부로 이전…“대상지 시군 공모”', content='<div class="box" style="margin-bottom:16px"><b>언론동향</b> · 작성자 박아현 · 게시일 2021-02-18<br><a href="https://grilu.kr/news/statement/000000ioy.html" style="color:var(--primary);text-decoration:underline;font-weight:700">▶ 본문·첨부파일 전문 보기</a></div><p style="line-height:1.8;color:#444">금일 GRI 및 경기도 언론기사/보도자료입니다.</p><p class="note">첨부: 연구원기사_링크_210218.hwp, 경기도_언론기사_210218.hwp, 경기도_보도자료_210218.hwp</p>', attachments='{"legacy_id": "gw-000000ioy", "page": "news/statement/000000ioy.html", "files": ["연구원기사_링크_210218.hwp", "경기도_언론기사_210218.hwp", "경기도_보도자료_210218.hwp"], "source": "gw.gri.re.kr 언론동향"}'::jsonb where attachments->>'legacy_id' = 'gw-000000ioy' and (board <> 'statement' or attachments->>'page' <> 'news/statement/000000ioy.html');
insert into public.posts (board,title,content,author_name,is_notice,attachments,created_at,updated_at) select 'documents','성희롱·성폭력 사건처리 매뉴얼','<div class="box" style="margin-bottom:16px"><b>성희롱·성폭력 신고센터</b> · 작성자 장영자 · 게시일 2020-12-31<br><a href="https://grilu.kr/archive/documents/000000im4.html" style="color:var(--primary);text-decoration:underline;font-weight:700">▶ 본문·첨부파일 전문 보기</a></div><p style="line-height:1.8;color:#444">「경기연구원 성희롱·성폭력 예방지침」(2020.11.24)을 바탕으로 성희롱·성폭력 사건 고충상담창구와 구체적 사건처리절차 및 피해자 보호조치 등을 매뉴얼화하여 게시합니다. &lt;주요 내용&gt; ○ 성희롱·성폭력 판단기준 ○ 성희롱·성폭력 2차 피해의 개념 및 예방조치 ○ 성희롱·성폭력 사건 내부 고충처리시스템 및 사건처리 세부절차 ○ 기관장, 관리자, 피해자, 동료근로자 등의 역할 및 대응 ○ 관련서식 등</p><p class="note">첨부: 경기연구원 성희롱성폭력 사건처리 매뉴얼(2020.12).hwp</p>','장영자',false,'{"legacy_id": "gw-000000im4", "page": "archive/documents/000000im4.html", "files": ["경기연구원 성희롱성폭력 사건처리 매뉴얼(2020.12).hwp"], "source": "gw.gri.re.kr 성희롱·성폭력 신고센터"}'::jsonb,'2020-12-31'::date,'2020-12-31'::date where not exists (select 1 from public.posts where attachments->>'legacy_id' = 'gw-000000im4');
