insert into public.posts (board,title,content,author_name,is_notice,attachments,created_at,updated_at) select 'documents','경기도 라떼파파 (성평등 캠페인)','<div class="box" style="margin-bottom:16px"><b>성희롱·성폭력 캠페인</b> · 작성자 김태중 · 게시일 2020-07-13<br><a href="https://grilu.kr/archive/documents/000000ick.html" style="color:var(--primary);text-decoration:underline;font-weight:700">▶ 본문·첨부파일 전문 보기</a></div><p style="line-height:1.8;color:#444">긍정적 남성이미지 확립 및 남녀 공동 육아 문화 인식 확산을 위해 &quot;경기도 라떼파파&quot; 영상을 공유합니다.</p><p class="note">첨부: ★라떼파파 영상.mp4, 라떼파파 메이킹 영상_WMV.wmv</p>','김태중',false,'{"legacy_id": "gw-000000ick", "page": "archive/documents/000000ick.html", "files": ["★라떼파파 영상.mp4", "라떼파파 메이킹 영상_WMV.wmv"], "source": "gw.gri.re.kr 성희롱·성폭력 캠페인"}'::jsonb,'2020-07-13'::date,'2020-07-13'::date where not exists (select 1 from public.posts where attachments->>'legacy_id' = 'gw-000000ick');
update public.posts set board='documents', title='경기도 라떼파파 (성평등 캠페인)', content='<div class="box" style="margin-bottom:16px"><b>성희롱·성폭력 캠페인</b> · 작성자 김태중 · 게시일 2020-07-13<br><a href="https://grilu.kr/archive/documents/000000ick.html" style="color:var(--primary);text-decoration:underline;font-weight:700">▶ 본문·첨부파일 전문 보기</a></div><p style="line-height:1.8;color:#444">긍정적 남성이미지 확립 및 남녀 공동 육아 문화 인식 확산을 위해 &quot;경기도 라떼파파&quot; 영상을 공유합니다.</p><p class="note">첨부: ★라떼파파 영상.mp4, 라떼파파 메이킹 영상_WMV.wmv</p>', attachments='{"legacy_id": "gw-000000ick", "page": "archive/documents/000000ick.html", "files": ["★라떼파파 영상.mp4", "라떼파파 메이킹 영상_WMV.wmv"], "source": "gw.gri.re.kr 성희롱·성폭력 캠페인"}'::jsonb where attachments->>'legacy_id' = 'gw-000000ick' and (board <> 'documents' or attachments->>'page' <> 'archive/documents/000000ick.html');
insert into public.posts (board,title,content,author_name,is_notice,attachments,created_at,updated_at) select 'documents','성희롱·성폭력 고충상담창구 안내','<div class="box" style="margin-bottom:16px"><b>성희롱·성폭력 신고센터</b> · 작성자 장영자 · 게시일 2020-05-13<br><a href="https://grilu.kr/archive/documents/000000i9c.html" style="color:var(--primary);text-decoration:underline;font-weight:700">▶ 본문·첨부파일 전문 보기</a></div><p style="line-height:1.8;color:#444">&lt; 안내사항 &gt; 성희롱·성폭력 고충상담창구를 아래와 같이 안내하오니 성희롱·성폭력 관련 고충이 있는 경우 고충상담원을 통해 상담신청하시기 바랍니다. *성희롱·성폭력 신고게시판(익명게시판)을 통한 고충 신청도 가능합니다. &lt;성희롱·성폭력 고충상담원 : 총 2명(인사복무담당자 1명 포함하여 남 1명, 여 1명) &gt; 구분 소속 성명 비고 1 행정지원부 장영자 여 2 대외협력부 조영진 남 *기타 고충처리 &lt;기간제 및 비정규직 고충처리 담당자&gt; 행정지원부(내선 269), 장영자 과장</p>','장영자',false,'{"legacy_id": "gw-000000i9c", "page": "archive/documents/000000i9c.html", "files": [], "source": "gw.gri.re.kr 성희롱·성폭력 신고센터"}'::jsonb,'2020-05-13'::date,'2020-05-13'::date where not exists (select 1 from public.posts where attachments->>'legacy_id' = 'gw-000000i9c');
update public.posts set board='documents', title='성희롱·성폭력 고충상담창구 안내', content='<div class="box" style="margin-bottom:16px"><b>성희롱·성폭력 신고센터</b> · 작성자 장영자 · 게시일 2020-05-13<br><a href="https://grilu.kr/archive/documents/000000i9c.html" style="color:var(--primary);text-decoration:underline;font-weight:700">▶ 본문·첨부파일 전문 보기</a></div><p style="line-height:1.8;color:#444">&lt; 안내사항 &gt; 성희롱·성폭력 고충상담창구를 아래와 같이 안내하오니 성희롱·성폭력 관련 고충이 있는 경우 고충상담원을 통해 상담신청하시기 바랍니다. *성희롱·성폭력 신고게시판(익명게시판)을 통한 고충 신청도 가능합니다. &lt;성희롱·성폭력 고충상담원 : 총 2명(인사복무담당자 1명 포함하여 남 1명, 여 1명) &gt; 구분 소속 성명 비고 1 행정지원부 장영자 여 2 대외협력부 조영진 남 *기타 고충처리 &lt;기간제 및 비정규직 고충처리 담당자&gt; 행정지원부(내선 269), 장영자 과장</p>', attachments='{"legacy_id": "gw-000000i9c", "page": "archive/documents/000000i9c.html", "files": [], "source": "gw.gri.re.kr 성희롱·성폭력 신고센터"}'::jsonb where attachments->>'legacy_id' = 'gw-000000i9c' and (board <> 'documents' or attachments->>'page' <> 'archive/documents/000000i9c.html');
insert into public.posts (board,title,content,author_name,is_notice,attachments,created_at,updated_at) select 'documents','직장 내 성희롱·성폭력 사건처리절차','<div class="box" style="margin-bottom:16px"><b>성희롱·성폭력 캠페인</b> · 작성자 김태중 · 게시일 2020-03-23<br><a href="https://grilu.kr/archive/documents/000000i59.html" style="color:var(--primary);text-decoration:underline;font-weight:700">▶ 본문·첨부파일 전문 보기</a></div><p style="line-height:1.8;color:#444">영상 다운로드 ○ 자료명 : 직장 내 성희롱·성폭력 사건처리절차 ○ 교육대상 : 공공기관/일반국민 및 중장년 ○ 자료내용 : 직장 내 성희롱 및 성폭력 실태를 알아보고, 사건처리절차에 대한 구체적인 정보를 제공하여 사건 대응력을 강화한다. ○ 분량 : 19분 2초 ○ 제작 : 2020년 / 여성가족부, 한국양성평등교육진흥원</p>','김태중',false,'{"legacy_id": "gw-000000i59", "page": "archive/documents/000000i59.html", "files": [], "source": "gw.gri.re.kr 성희롱·성폭력 캠페인"}'::jsonb,'2020-03-23'::date,'2020-03-23'::date where not exists (select 1 from public.posts where attachments->>'legacy_id' = 'gw-000000i59');
update public.posts set board='documents', title='직장 내 성희롱·성폭력 사건처리절차', content='<div class="box" style="margin-bottom:16px"><b>성희롱·성폭력 캠페인</b> · 작성자 김태중 · 게시일 2020-03-23<br><a href="https://grilu.kr/archive/documents/000000i59.html" style="color:var(--primary);text-decoration:underline;font-weight:700">▶ 본문·첨부파일 전문 보기</a></div><p style="line-height:1.8;color:#444">영상 다운로드 ○ 자료명 : 직장 내 성희롱·성폭력 사건처리절차 ○ 교육대상 : 공공기관/일반국민 및 중장년 ○ 자료내용 : 직장 내 성희롱 및 성폭력 실태를 알아보고, 사건처리절차에 대한 구체적인 정보를 제공하여 사건 대응력을 강화한다. ○ 분량 : 19분 2초 ○ 제작 : 2020년 / 여성가족부, 한국양성평등교육진흥원</p>', attachments='{"legacy_id": "gw-000000i59", "page": "archive/documents/000000i59.html", "files": [], "source": "gw.gri.re.kr 성희롱·성폭력 캠페인"}'::jsonb where attachments->>'legacy_id' = 'gw-000000i59' and (board <> 'documents' or attachments->>'page' <> 'archive/documents/000000i59.html');
insert into public.posts (board,title,content,author_name,is_notice,attachments,created_at,updated_at) select 'statement','[3/6 GRI·경기도 기사] 경기도, 도 산하 공공기관 통합채용 연 2→3회로 늘린다','<div class="box" style="margin-bottom:16px"><b>언론동향</b> · 작성자 박아현 · 게시일 2020-03-06<br><a href="https://grilu.kr/news/statement/000000i4n.html" style="color:var(--primary);text-decoration:underline;font-weight:700">▶ 본문·첨부파일 전문 보기</a></div><p style="line-height:1.8;color:#444">금일 경기도 언론기사/보도자료입니다. 1. 경기도 언론기사 2. 경기도 보도자료 # GRI 언론기사는 없습니다.</p><p class="note">첨부: 경기도_언론기사_200306.hwp, 경기도_보도자료_200306.hwp</p>','박아현',false,'{"legacy_id": "gw-000000i4n", "page": "news/statement/000000i4n.html", "files": ["경기도_언론기사_200306.hwp", "경기도_보도자료_200306.hwp"], "source": "gw.gri.re.kr 언론동향"}'::jsonb,'2020-03-06'::date,'2020-03-06'::date where not exists (select 1 from public.posts where attachments->>'legacy_id' = 'gw-000000i4n');
